def fizz_buzz(n: int):
    """Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13.
    >>> fizz_buzz(50)
    0
    >>> fizz_buzz(78)
    2
    >>> fizz_buzz(79)
    3
    """
    if n <= 0:
        return 0

    def count_sevens_up_to(limit, modulus):
        if limit < 0:
            return 0

        digits = str(limit)
        equal = {0: (1, 0)}
        less = {}

        for ch in digits:
            max_digit = ord(ch) - 48
            new_equal = {}
            new_less = {}

            for mod, (cnt, prefix_sum) in equal.items():
                if cnt == 0:
                    continue

                for d in range(max_digit):
                    next_mod = (mod * 10 + d) % modulus
                    add = cnt if d == 7 else 0
                    current = new_less.get(next_mod, (0, 0))
                    new_less[next_mod] = (
                        current[0] + cnt,
                        current[1] + prefix_sum + add,
                    )

                d = max_digit
                next_mod = (mod * 10 + d) % modulus
                add = cnt if d == 7 else 0
                current = new_equal.get(next_mod, (0, 0))
                new_equal[next_mod] = (
                    current[0] + cnt,
                    current[1] + prefix_sum + add,
                )

            for mod, (cnt, prefix_sum) in less.items():
                if cnt == 0:
                    continue

                for d in range(10):
                    next_mod = (mod * 10 + d) % modulus
                    add = cnt if d == 7 else 0
                    current = new_less.get(next_mod, (0, 0))
                    new_less[next_mod] = (
                        current[0] + cnt,
                        current[1] + prefix_sum + add,
                    )

            equal, less = new_equal, new_less

        total = less.get(0, (0, 0))[1]
        total += equal.get(0, (0, 0))[1]
        return total

    upper = n - 1
    return (
        count_sevens_up_to(upper, 11)
        + count_sevens_up_to(upper, 13)
        - count_sevens_up_to(upper, 143)
    )

