    left_associative = {'+', '-', '*', '//'}

    def apply(op, left, right):
        if op == '+':
            return left + right
        elif op == '-':
            return left - right
        elif op == '*':
            return left * right
        elif op == '//':
            return left // right
        else:
            return left ** right

    values = [operand[0]]
    ops = []

    for i, op in enumerate(operator):
        values.append(operand[i + 1])

        while ops:
            top = ops[-1]
            top_prec = precedence[top]
            cur_prec = precedence[op]

            if top_prec > cur_prec or (top_prec == cur_prec and top in left_associative):
                op_top = ops.pop()
                right = values.pop()
                left = values.pop()
